import { mockedImports } from 'virtual:nuxt-storybook/mocked-imports'
import type { Mock } from 'storybook/test'
import { registerFileMock } from './mocks'
import type { Procedure } from './mocks'

// Generated by Nuxt in `.nuxt/imports.d.ts`: the project's composables and
// utils, the modules' and Nuxt's own
type NuxtImports = typeof import('#imports')

/** The auto-imports that are functions: the only ones that can be spied. */
export type MockableImport = {
  [Name in keyof NuxtImports]: NuxtImports[Name] extends Procedure
    ? Name
    : never
}[keyof NuxtImports]

/**
 * Mocks a Nuxt auto-import for every story of the file, as `mockNuxtImport`
 * of `@nuxt/test-utils` does, and returns its `storybook/test` spy. Only valid
 * at the top level of a story file: the build reads the name and appends the
 * file, so both must be static. The factory runs once per story.
 */
export const mockNuxtImport = register as <Name extends MockableImport>(
  name: Name | string,
  factory?: () => NuxtImports[Name],
) => Mock<NuxtImports[Name]>

function register(
  name: string,
  factory?: () => Procedure,
  // Injected by the Vite plugin, which knows the story file that called `mockNuxtImport()`
  file?: string,
): Mock {
  if (file === undefined) {
    throw new Error(
      `mockNuxtImport('${name}') must be called at the top level of a story file`,
    )
  }
  const spy = mockedImports[name]
  if (!spy) {
    throw new Error(
      `mockNuxtImport('${name}'): the name was not found when Storybook started. Restart it after adding mocks.`,
    )
  }
  if (factory) {
    registerFileMock(file, name, factory)
  }
  return spy
}
